// utils/roleSlug.js
//
// Role slugs are generated by the backend from the role name.
// The Create Role form has no slug field, so the user can never correct one —
// any name the form accepts must produce a valid slug.
//
//   "test role r2"     → "test_role_r2"
//   "  HR - Payroll! " → "hr_payroll"
//   "2nd Shift Lead"   → "role_2nd_shift_lead"   (must start with a letter)

"use strict";

const SLUG_PATTERN = /^[a-z][a-z0-9_]*$/;
const SLUG_MAX_LENGTH = 50;

const slugifyRoleName = (value) => {
  let slug = String(value || "")
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "") // strip accents
    .replace(/[^a-z0-9]+/g, "_")     // anything else → underscore
    .replace(/^_+|_+$/g, "");        // trim underscores

  if (!slug) return "";
  if (!/^[a-z]/.test(slug)) slug = `role_${slug}`;
  return slug.slice(0, SLUG_MAX_LENGTH).replace(/_+$/g, "");
};

module.exports = { slugifyRoleName, SLUG_PATTERN, SLUG_MAX_LENGTH };